// Soft-update while awaiting OTP so poll does not wipe digits the user is typing

window.piAirbnbBrowserRender = function (job) {
  if (job) piRenderAirbnbConnect(job);
  if (job && job.status === 'connected') {
    if (window._piAirbnbLoginTimer) { clearInterval(window._piAirbnbLoginTimer); window._piAirbnbLoginTimer = null; }
    msg('Airbnb connected — session saved for Pull', true);
    piReload();
  }
};
window.piAirbnbBrowserRequest = async function (path, payload) {
  var id = window._piAirbnbLoginId;
  if (!id) throw new Error('No active Airbnb browser');
  var res = await fetch('/api/platform-invoices/sessions/airbnb/login/' + encodeURIComponent(id) + '/browser/' + path, {
    method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(payload || {})
  });
  var j = await res.json();
  if (!res.ok) throw new Error((j && j.error) || 'Airbnb browser action failed');
  piAirbnbBrowserRender(j.job);
  return j;
};
window.piAirbnbBrowserClick = async function (ev) {
  var img = ev && ev.currentTarget;
  if (!img) return;
  var rect = img.getBoundingClientRect();
  var x = Math.round((ev.clientX - rect.left) * (img.naturalWidth || 1440) / rect.width);
  var y = Math.round((ev.clientY - rect.top) * (img.naturalHeight || 900) / rect.height);
  img.style.opacity = '0.55';
  try { await piAirbnbBrowserRequest('click', { x: x, y: y }); }
  catch (e) { img.style.opacity = '1'; msg(e.message || String(e), false); }
};
window.piAirbnbBrowserType = async function () {
  var input = document.getElementById('pi-airbnb-browser-text');
  var text = input ? String(input.value || '') : '';
  if (!text) { msg('Type a value first', false); return; }
  if (input) { input.value = ''; input.disabled = true; }
  try { await piAirbnbBrowserRequest('type', { text: text }); }
  catch (e) { msg(e.message || String(e), false); }
  finally { if (input) input.disabled = false; }
};
window.piAirbnbBrowserKey = async function (key) {
  try { await piAirbnbBrowserRequest('key', { key: key }); }
  catch (e) { msg(e.message || String(e), false); }
};
window.piAirbnbBrowserRefresh = async function () {
  try { await piAirbnbBrowserRequest('refresh', {}); }
  catch (e) { msg(e.message || String(e), false); }
};
